"""docs/METRICS.md, generated from config/metrics.yaml so the documentation is the definition."""

from __future__ import annotations

from apr import conf
from apr.semantic.layer import catalog


def metrics_doc() -> str:
    cat = catalog()
    lines = [
        "# Metrics",
        "",
        "Generated by `apr generate` from `config/metrics.yaml`. Ask questions about these metrics in plain "
        "English (`apr ask`, the console's Ask tab, `POST /api/ask`), or send a metric query "
        "(`POST /api/semantic/query`).",
        "",
        "| Metric | What it is | Unit | Can be broken down by | Time |",
        "|---|---|---|---|---|",
    ]
    for name, m in cat["metrics"].items():
        src = cat["sources"][m["source"]]
        dims = ", ".join(cat["dimensions"][d]["label"].lower() for d in src["dimensions"])
        floor = src.get("grain_floor")
        when = "whole months only" if floor == "month" else "any day"
        lines.append(
            f"| `{name}` ({m['label']}) | {m['description']} | {'EUR' if m['unit'] == 'eur' else 'count'} "
            f"| {dims} | {when} |"
        )
    lines += ["", "## Dimensions", "", "| Dimension | Values |", "|---|---|"]
    for name, d in cat["dimensions"].items():
        vals = ", ".join(f"`{v}`" for v in d.get("values", [])) or (
            "ISO country codes of the 18 markets: " + ", ".join(f"`{c}`" for c in conf.read("world")["countries"])
            if name == "country"
            else ""
        )
        if name == "asset_class":
            vals = "`stock`, `etf`, `crypto`, `bond`"
        lines.append(f"| `{name}` ({d['label']}) | {vals} |")
    lines += [
        "",
        "## Time",
        "",
        '- Periods are relative to the last complete day of data ("data through"), not to the clock.',
        '- "Last month" is the last complete calendar month; "this month" runs from the 1st to the last '
        'complete day. Weeks start on Monday; "last week" is the last complete Monday-to-Sunday week.',
        '- "Last N days" ends on the last complete day and includes it.',
        "- Quarters are calendar quarters. A named month without a year is in the current year.",
        f"- Without a period, a question covers the last {cat['time']['default_window_days']} days, or the last "
        "complete month for monthly metrics.",
        "- Breakdowns over time: daily, weekly, monthly, quarterly. Monthly metrics cannot be broken down by "
        "day or week, and their periods must be whole months (the current month counts while it is running).",
        "",
        "## What is not answered",
        "",
        "- Anything about individual customers (names, e-mails, IBANs, who did what): use governed SQL.",
        '- Forecasts, and "why" questions.',
        "- Metrics, dimensions or values not listed here.",
        "",
    ]
    return "\n".join(lines)


def write_metrics_doc() -> str:
    p = conf.path("docs", "METRICS.md")
    p.write_text(metrics_doc(), encoding="utf-8")
    return str(p)
